INSERT INTO meme_phrases (id, text, tags, language, created_at) VALUES
    ('c1000000-0000-0000-0000-000000000001', 'Staring into the distance... okay, staring at the wallpaper.', '["피곤", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000002', 'This is what they call the "customer service smile."', '["직장인", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000003', 'What are you looking at? Never seen something this cute?', '["귀여움", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000004', 'Sure, got it. I have no idea what''s going on.', '["피곤", "직장인", "눈치"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000005', 'I''m home and I still want to go home.', '["피곤", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000006', 'My motivation clocked out hours ago.', '["피곤", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000007', 'Can someone live my best life for me?', '["피곤", "질문", "의지"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000008', 'No, seriously, is this a joke?', '["분노", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000009', 'Today''s to-do: pass it on to tomorrow-me.', '["의지", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000010', 'Can I just go home now?', '["직장인", "눈치", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000011', 'I want to break this monitor. (literally)', '["직장인", "분노", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000012', 'Sure thing! (internally screaming no)', '["직장인", "눈치", "분노"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000013', 'Look at this small precious thing. Me.', '["귀여움"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000014', 'Are you seriously ignoring me right now?', '["분노", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000015', 'No treats, no talk. Walk away.', '["의지", "분노"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000016', 'Am I... a little cute, maybe?', '["귀여움", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000017', 'But hey — who else is gonna make you laugh?', '["귀여움", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000018', 'The world is big and full of good food.', '["기쁨", "의지"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000019', 'My MBTI is CUTE.', '["귀여움", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000020', 'Wait, give me my weekend back.', '["분노", "주말", "놀람"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000021', 'Me, 5 minutes before clocking out on Friday.', '["기쁨", "직장인", "주말"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000022', 'I can''t believe I woke up at 9am on a Saturday.', '["놀람", "주말", "분노"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000023', 'I''m sorry, what did you just say?', '["놀람", "질문", "눈치"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000024', 'Um... did you call my name?', '["직장인", "눈치", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000025', 'This weekend''s workout: breathing. That''s it.', '["주말", "의지", "피곤"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000026', 'Do I actually have to do this?', '["직장인", "질문", "분노"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000027', 'Wow, it''s Monday already? (losing it)', '["놀람", "광기", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000028', 'Currently doubting my own eyes.', '["놀람"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000029', 'This smile? Not a real smile.', '["피곤", "광기", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000030', 'When I say I''ll do it, I mean it. That''s me.', '["의지", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000031', 'Bring it on! ...actually, please don''t.', '["의지", "눈치"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000032', 'Starting today, I''m living my best life. (starting tomorrow)', '["의지", "광기", "귀여움"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000033', 'I swear I cleaned this. Why is it a mess again?', '["놀람", "질문"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000034', 'I''m not mad. I swear.', '["분노", "눈치", "귀여움"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000035', 'Should I eat this or not?', '["질문", "눈치"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000036', 'Oops, caught red-handed.', '["놀람", "귀여움"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000037', 'Shh. My inner dark side is stirring.', '["광기", "귀여움"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000038', 'I am absolutely not sleeping tonight.', '["의지", "피곤"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000039', 'Bed and I are now one being.', '["기쁨", "주말", "피곤"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000040', 'Excuse me, you just crossed a line.', '["분노", "눈치"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000041', 'Only snacks can make me move.', '["의지", "기쁨"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000042', 'This is my best. What do you want from me.', '["직장인", "분노", "광기"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000043', 'Read the room.', '["눈치", "의지"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000044', 'I did nothing and it''s already evening?', '["놀람", "질문", "주말"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000045', 'Sorry, me? This? Right now?', '["질문", "놀람", "직장인"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000046', 'World, why are you like this to me.', '["피곤", "분노"]', 'en', NOW()),
    ('c1000000-0000-0000-0000-000000000047', 'Honestly? This works out better.', '["광기", "기쁨", "의지"]', 'en', NOW()),
